def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))

            r1 = min(y for y,x in comp)
            r2 = max(y for y,x in comp)
            c1 = min(x for y,x in comp)
            c2 = max(x for y,x in comp)
            if r2-r1 < 2 or c2-c1 < 2:
                continue

            perimeter = set()
            for x in range(c1, c2+1):
                perimeter.add((r1,x))
                perimeter.add((r2,x))
            for y in range(r1, r2+1):
                perimeter.add((y,c1))
                perimeter.add((y,c2))
            if comp != perimeter:
                continue

            fill = 2 if (r2-r1-1, c2-c1-1) == (2,2) else 7
            for y in range(r1+1, r2):
                for x in range(c1+1, c2):
                    out[y][x] = fill
    return out
